    vocabulary: [["ursprünglich", "originally", "Ich komme ursprünglich aus Chile."], ["die Erfahrung, -en", "experience", "Ich habe Erfahrung im Verkauf."], ["das Ziel, -e", "goal", "Mein Ziel ist ein Gespräch ohne Hilfe."], ["sich verbessern", "to improve", "Ich möchte mich im Schreiben verbessern."], ["die Voraussetzung, -en", "prerequisite", "A2 ist eine Voraussetzung für diesen Kurs."], ["regelmäßig", "regularly", "Ich übe regelmäßig mit einer Partnerin."]],
